function adapter(str, options) {
  if (typeof str !== 'string') {
    return str;
  }

  options = options || {};

  // Ordered list of variable sources. Later sources take precedence
  // (i.e. are checked first) matching Bruno's interpolation precedence.
  var sources = [
    options.processEnvVars,
    options.globalEnvironmentVariables,
    options.collectionVariables,
    options.envVars,
    options.folderVariables,
    options.requestVariables,
    options.runtimeVariables,
    options.promptVariables,
    options.secretVariables
  ];

  function lookup(name) {
    // Iterate from highest precedence to lowest.
    for (var i = sources.length - 1; i >= 0; i--) {
      var src = sources[i];
      if (src && typeof src === 'object' && Object.prototype.hasOwnProperty.call(src, name)) {
        var val = src[name];
        if (val === undefined || val === null) {
          return '';
        }
        return String(val);
      }
    }
    return undefined;
  }

  // Replace {{variable}} placeholders. Variable names may contain
  // letters, digits, underscores, dots, hyphens and spaces.
  return str.replace(/\{\{\s*([^{}]+?)\s*\}\}/g, function (match, rawName) {
    var name = rawName.trim();
    var resolved = lookup(name);
    if (resolved === undefined) {
      // Leave unresolved placeholders untouched.
      return match;
    }
    return resolved;
  });
}

