function adapter(str, options) {
  options = options || {};

  // ---- lodash get (path string, dot notation) ----
  function get(obj, path) {
    if (obj == null) return undefined;
    if (typeof path !== 'string') return undefined;
    // lodash: if the exact key exists on the object, return it directly.
    if (Object.prototype.hasOwnProperty.call(Object(obj), path)) {
      return obj[path];
    }
    var keys = [];
    var re = /[^.[\]]+|\[(?:(-?\d+(?:\.\d+)?)|(["'])((?:(?!\2)[^\\]|\\.)*?)\2)\]/g;
    var m;
    while ((m = re.exec(path)) !== null) {
      if (m[1] !== undefined) keys.push(m[1]);
      else if (m[3] !== undefined) keys.push(m[3].replace(/\\(.)/g, '$1'));
      else keys.push(m[0]);
    }
    var cur = obj;
    for (var i = 0; i < keys.length; i++) {
      if (cur == null) return undefined;
      cur = cur[keys[i]];
    }
    return cur;
  }

  function isPlainObject(v) {
    if (v === null || typeof v !== 'object') return false;
    var proto = Object.getPrototypeOf(v);
    return proto === Object.prototype || proto === null;
  }

  // Mock data functions ({{$keyword}}) are not available in this environment;
  // the original leaves unknown keywords untouched, which we replicate.
  var MOCK_PATTERN = /\{\{\$(\w+)\}\}/g;
  function prepareMock(s) {
    return s.replace(MOCK_PATTERN, function (match) { return match; });
  }
  function prepareMockObj(obj) {
    var processed = {};
    for (var key in obj) {
      if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
      var value = obj[key];
      if (typeof value === 'string') {
        processed[key] = prepareMock(value);
      } else if (isPlainObject(value)) {
        processed[key] = prepareMockObj(value);
      } else {
        processed[key] = value;
      }
    }
    return processed;
  }

  function replace(str, obj, visited, results) {
    visited = visited || new Set();
    results = results || new Map();
    var resultStr = str;
    var matchFound = true;
    while (matchFound) {
      var patternRegex = /\{\{([^}]+)\}\}/g;
      matchFound = false;
      resultStr = resultStr.replace(patternRegex, function (match, placeholder) {
        var replacement = get(obj, placeholder);
        if (typeof replacement === 'object' && replacement !== null) {
          replacement = JSON.stringify(replacement);
        }
        if (results.has(match)) {
          return results.get(match);
        }
        if (patternRegex.test(replacement) && !visited.has(match)) {
          visited.add(match);
          var result = replace(replacement, obj, visited, results);
          results.set(match, result);
          matchFound = true;
          return result;
        }
        visited.add(match);
        var result2 = replacement !== undefined ? replacement : match;
        results.set(match, result2);
        matchFound = true;
        return result2;
      });
    }
    return resultStr;
  }

  function interpolate(s, obj) {
    if (!s || typeof s !== 'string') return s;
    var preparedStr = prepareMock(s);
    if (!obj || typeof obj !== 'object') return preparedStr;
    var preparedObj = prepareMockObj(obj);
    return replace(preparedStr, preparedObj);
  }

  var globalEnvironmentVariables = options.globalEnvironmentVariables;
  var collectionVariables = options.collectionVariables;
  var envVars = options.envVars;
  var folderVariables = options.folderVariables;
  var requestVariables = options.requestVariables;
  var runtimeVariables = options.runtimeVariables;
  var processEnvVars = options.processEnvVars;
  var promptVariables = options.promptVariables;
  var secretVariables = options.secretVariables || {};

  processEnvVars = processEnvVars || {};
  runtimeVariables = runtimeVariables || {};
  globalEnvironmentVariables = globalEnvironmentVariables || {};
  collectionVariables = collectionVariables || {};
  folderVariables = folderVariables || {};
  requestVariables = requestVariables || {};
  promptVariables = promptVariables || {};

  // clone envVars so we don't mutate the caller's object
  envVars = envVars ? JSON.parse(JSON.stringify(envVars)) : {};

  // envVars may themselves contain {{process.env.VAR}} references
  for (var key in envVars) {
    if (!Object.prototype.hasOwnProperty.call(envVars, key)) continue;
    envVars[key] = interpolate(envVars[key], {
      process: { env: Object.assign({}, processEnvVars) }
    });
  }

  var combined = Object.assign(
    {},
    globalEnvironmentVariables,
    collectionVariables,
    envVars,
    folderVariables,
    requestVariables,
    runtimeVariables,
    promptVariables,
    { process: { env: Object.assign({}, processEnvVars) } },
    secretVariables
  );

  if (!str || !str.length || typeof str !== 'string') {
    return str;
  }
  return interpolate(str, combined);
}
